def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    rich_aggressive = 0
    desperate_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) >= 90 and opp.get('budget', 0) >= 200:
                    rich_aggressive += 1

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    tight_supply = supply <= 17
    abundant_supply = supply >= 22

    urgency = 0
    if hp <= 2:
        urgency += 4
    elif hp <= 4:
        urgency += 2
    if no_water_days >= 2:
        urgency += 4
    elif no_water_days >= 1:
        urgency += 2
    if tight_supply:
        urgency += 2
    elif abundant_supply:
        urgency -= 1
    if day >= 8:
        urgency += 1

    if urgency >= 7:
        target = max(92.0, highest_prev + 3.0)
    elif urgency >= 5:
        target = max(72.0, avg_prev + 4.0, highest_prev * 0.78)
    elif urgency >= 3:
        target = max(44.0, avg_prev * 0.72)
    else:
        target = 22.0 if abundant_supply else 30.0

    if rich_aggressive >= 1 and urgency <= 3:
        target = min(target, 26.0 if abundant_supply else 32.0)

    if desperate_count >= 2 and urgency >= 3:
        target += 8.0

    if highest_prev >= 110:
        if urgency <= 3:
            target = min(target, 24.0)
        else:
            target = max(target, 84.0)
    elif highest_prev >= 80 and urgency <= 2:
        target = min(target, 28.0)

    if hp >= 8 and no_water_days == 0 and abundant_supply and day <= 4:
        target = min(target, 20.0)

    max_safe = budget
    if hp > 4 and no_water_days == 0:
        max_safe = min(max_safe, budget * 0.55)
    elif hp > 2:
        max_safe = min(max_safe, budget * 0.75)

    bid = min(target, max_safe)

    if hp <= 2 or no_water_days >= 2:
        bid = min(budget, max(bid, 95.0))
    elif hp <= 4 or no_water_days >= 1:
        bid = min(budget, max(bid, 68.0))

    if bid < 0:
        bid = 0.0

    return float(round(min(budget, bid), 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Alive opponents
    alive_opponents = []
    for oid, o in opponents_status.items():
        if o.get('alive'):
            alive_opponents.append(o)

    # If no opponents, bid to ensure allocation but not overpay
    if not alive_opponents:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace only (immediate reaction)
    yesterday_bids = []
    for o in alive_opponents:
        prev = o.get('previous_trace', {})
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    hp = int(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    # Determine a target bid level based on yesterday's observed aggressiveness
    # If someone was bidding very low, the market may be weak today.
    low_bid = None
    high_bid = None
    if yesterday_bids:
        low_bid = min(yesterday_bids)
        high_bid = max(yesterday_bids)

    # Urgency factor: if we already missed water, increase bid.
    urgency = 0.0
    if no_water_days >= 2:
        urgency = 0.35
    elif no_water_days == 1:
        urgency = 0.18

    # HP safety: if low HP, increase bid.
    if hp <= 2:
        urgency += 0.35
    elif hp <= 4:
        urgency += 0.18

    # Supply pressure: lower supply => higher chance others compete; scale up.
    supply_pressure = 0.0
    if supply <= float(MIN_SUPPLY):
        supply_pressure = 0.25
    elif supply >= float(MAX_SUPPLY):
        supply_pressure = -0.05
    else:
        # linear between 15 and 25
        supply_pressure = 0.25 - 0.25 * ((supply - float(MIN_SUPPLY)) / (float(MAX_SUPPLY) - float(MIN_SUPPLY)))

    # Base bid: aim around mid of DAILY_SALARY with adjustments.
    # Yesterday had survivors with ~88-99 avg; use that as anchor.
    base = DAILY_SALARY * 0.62  # 55.8

    # If high_bid was large, we should not be too low; if low_bid was tiny, we can undercut.
    adjust = 0.0
    if high_bid is not None and high_bid >= DAILY_SALARY * 1.1:
        adjust += 0.12
    if low_bid is not None and low_bid <= DAILY_SALARY * 0.35:
        adjust -= 0.08

    target = base * (1.0 + urgency + supply_pressure + adjust)

    # Cap target to avoid overspending; also ensure we can afford it.
    # If we are very low on budget, bid a fraction.
    if budget <= DAILY_SALARY * 0.6:
        target = min(target, budget * 0.9)
    else:
        target = min(target, budget * 0.55)

    # If we are at/near critical HP, bid more aggressively.
    if hp <= 1:
        target = min(budget, DAILY_SALARY * 0.95)
    elif hp <= 3:
        target = min(budget, DAILY_SALARY * (0.75 + urgency))

    # Final sanity: bid at least a small amount if possible.
    min_bid = 1.0
    if budget < min_bid:
        return float(budget)

    bid = float(min(max(target, min_bid), budget))
    return bid
